using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public record UnifiedReportRequest(string Report,Guid? UnitId=null,DateOnly? From=null,DateOnly? To=null,string? Status=null,string Format="csv",Guid? EntityId=null);
public record UnifiedPage(int Total,IReadOnlyList<JsonElement> Items,string Basis="Authorized canonical records");
public class UnifiedIntelligence(AppDb db,Access a,CommunityService community,FinanceService finance,ServiceProjectService service){
 public static readonly string[] Reports=["Societies","Regions","Chapters","Members","Leadership","Membership Growth","Activities","Events","Attendance","Communication","Member Dues","Chapter Dues","Payments","Service Projects","Volunteer Hours","ID Cards","Certificates"];
 static JsonElement Json(object value)=>JsonSerializer.SerializeToElement(value,FinanceExport.Web);
 public async Task<object> Summary(Guid tenant,Guid? workspace,DateOnly? from=null,DateOnly? to=null){await a.Member(tenant);var start=from??new DateOnly(FinanceService.Today.Year,FinanceService.Today.Month,1);var end=to??FinanceService.Today;if(end<start||end>start.AddYears(10))throw new DomainException("Choose a date range up to ten years");var begin=start.ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);var through=end.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);var units=a.InWorkspace(a.Visible(tenant,"intelligence.read"),tenant,workspace);var ids=units.Select(u=>u.Id);var members=db.Memberships.Where(m=>m.TenantId==tenant&&ids.Contains(m.ChapterId));var current=members.Where(m=>m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow));var projects=service.Visible(tenant,workspace);var projectIds=projects.Select(p=>p.Id);var posts=community.Posts(tenant).Where(p=>p.Status=="Published"&&p.PublishedAt>=begin&&p.PublishedAt<through&&(workspace==null||p.UnitId!=null&&ids.Contains(p.UnitId.Value)));var events=community.Events(tenant).Where(e=>e.Status=="Published"&&e.StartsAt>=begin&&e.StartsAt<through&&(workspace==null||e.UnitId!=null&&ids.Contains(e.UnitId.Value)));var attendanceUnits=a.InWorkspace(a.Visible(tenant,"events.analytics"),tenant,workspace).Select(u=>u.Id);var attendance=db.Set<EventAttendance>().Where(v=>v.TenantId==tenant&&!v.Voided&&v.At>=begin&&v.At<through&&db.Set<CommunityEvent>().Any(e=>e.TenantId==tenant&&e.Id==v.EventId&&e.UnitId!=null&&attendanceUnits.Contains(e.UnitId.Value)));
  var invoices=finance.Scoped<FinanceInvoice>(tenant,entity:null,workspace:workspace).Where(i=>i.Kind=="Invoice"&&i.Status=="Issued");var payments=finance.Scoped<FinancePayment>(tenant,entity:null,workspace:workspace).Where(p=>p.Status=="Confirmed"&&p.Date>=start&&p.Date<=end);var financeEntities=finance.Scoped<FinancialUnit>(tenant,entity:null,workspace:workspace).Select(u=>u.EntityId);var communicationsUnits=a.InWorkspace(a.Visible(tenant,"communications.analytics"),tenant,workspace).Select(u=>u.Id);var deliveries=db.Outbox.Where(o=>o.TenantId==tenant&&o.UnitId!=null&&communicationsUnits.Contains(o.UnitId.Value)&&o.CreatedAt>=begin&&o.CreatedAt<through);
  return new{from=start,to=end,definitions="Unique people and memberships are distinct. Impact and hours include verified records only. Joint projects are canonical once. Financial totals remain separated by legal entity and currency.",counts=new{regions=await units.CountAsync(u=>db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Region")),chapters=await units.CountAsync(u=>db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")),uniquePeople=await current.Select(m=>m.PersonId).Distinct().CountAsync(),memberships=await current.CountAsync(),newMemberships=await members.CountAsync(m=>m.JoinedAt>=begin&&m.JoinedAt<through),activities=await posts.CountAsync(),events=await events.CountAsync(),attendance=await attendance.CountAsync(),peopleAttended=await attendance.SumAsync(v=>v.PeopleCount),projects=await projects.CountAsync(),pendingProjects=await projects.CountAsync(p=>p.Status=="Pending Approval"),issuedCards=await db.Set<Credential>().CountAsync(c=>c.TenantId==tenant&&c.UnitId!=null&&ids.Contains(c.UnitId.Value)&&c.Kind=="Card"&&c.Status=="Issued"&&c.ExpiryDate>=FinanceService.Today),certificates=await db.Set<Credential>().CountAsync(c=>c.TenantId==tenant&&c.UnitId!=null&&ids.Contains(c.UnitId.Value)&&c.Kind=="Certificate"&&c.Status=="Issued"),verifiedVolunteerHours=await db.Set<VolunteerAttendance>().Where(v=>v.TenantId==tenant&&v.Status=="Verified"&&v.CheckedIn>=begin&&v.CheckedIn<through&&db.Set<VolunteerShift>().Any(s=>s.Id==v.ShiftId&&projectIds.Contains(s.ProjectId))).SumAsync(v=>v.Hours)},growth=await members.Where(m=>m.JoinedAt>=begin&&m.JoinedAt<through).GroupBy(m=>new{m.JoinedAt.Year,m.JoinedAt.Month}).OrderBy(g=>g.Key.Year).ThenBy(g=>g.Key.Month).Select(g=>new{year=g.Key.Year,month=g.Key.Month,memberships=g.Count(),uniquePeople=g.Select(m=>m.PersonId).Distinct().Count()}).ToListAsync(),membershipDistribution=await(from m in current join u in db.Units on m.ChapterId equals u.Id group m by new{u.Id,u.Name} into g orderby g.Count() descending select new{g.Key.Id,g.Key.Name,memberships=g.Count(),people=g.Select(m=>m.PersonId).Distinct().Count()}).Take(50).ToListAsync(),impact=await(from x in db.Set<ImpactResult>() join metric in db.Set<ImpactMetric>() on x.MetricId equals metric.Id where x.TenantId==tenant&&x.Status=="Verified"&&projectIds.Contains(x.ProjectId)&&x.At>=begin&&x.At<through group x by new{metric.Id,metric.Name,metric.Unit,metric.Aggregation} into g select new{g.Key.Id,g.Key.Name,g.Key.Unit,value=g.Key.Aggregation=="Max"?g.Max(x=>x.Value):g.Key.Aggregation=="Count"?g.Count():g.Sum(x=>x.Value),g.Key.Aggregation}).ToListAsync(),finance=await db.Set<FinancialEntity>().Where(e=>e.TenantId==tenant&&financeEntities.Contains(e.Id)).Select(e=>new{e.Id,e.Name,e.Currency,outstanding=invoices.Where(i=>i.EntityId==e.Id).Sum(i=>i.Total-i.Paid-i.Credited),collections=payments.Where(p=>p.EntityId==e.Id).Sum(p=>p.Amount-p.Refunded-p.ChargedBack)}).ToListAsync(),communications=await deliveries.GroupBy(o=>o.Status).Select(g=>new{status=g.Key,count=g.Count()}).ToListAsync()};
 }
 public async Task<UnifiedPage> Report(Guid tenant,UnifiedReportRequest r,int page=1){await a.Member(tenant);if(!Reports.Contains(r.Report)||page<1||page>2000)throw new DomainException("Choose a supported report and page");await a.Require(tenant,"reports.export",r.UnitId);var sourceModule=r.Report switch{"Members" or "Membership Growth" or "Leadership"=>"membership","Activities" or "Events" or "Attendance"=>"community","Communication"=>"communications","Member Dues" or "Chapter Dues" or "Payments"=>"finance","Service Projects" or "Volunteer Hours"=>"service","ID Cards" or "Certificates"=>"studio",_=>""};if(sourceModule!=""&&!await PlatformPolicy.WorkAllowed(db,tenant,sourceModule))throw new AccessDeniedException();if(r.To!=null&&r.From!=null&&r.To<r.From)throw new DomainException("Report end precedes start");var begin=(r.From??new DateOnly(1900,1,1)).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);var through=(r.To??FinanceService.Today).AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);var skip=(page-1)*100;
  async Task<UnifiedPage> Rows<T>(IQueryable<T> q){var total=await q.CountAsync();var rows=await q.Skip(skip).Take(100).ToListAsync();return new(total,rows.Select(x=>Json(x!)).ToArray());}
  if(r.Report is "Societies" or "Regions" or "Chapters"){if(r.Report=="Societies"){await a.Require(tenant,"units.read");return new(1,page==1?[Json(await db.Tenants.Where(t=>t.Id==tenant).Select(t=>new{t.Id,t.Name,t.Status}).SingleAsync())]:[]);}var q=a.InWorkspace(a.Visible(tenant,"units.read"),tenant,r.UnitId);var kind=r.Report=="Regions"?"Region":"Chapter";return await Rows(q.Where(u=>db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind==kind)&&(r.Status==null||u.Status==r.Status)).OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name,u.Code,u.Status,u.ParentId}));}
  if(r.Report is "Members" or "Membership Growth"){await a.Require(tenant,"members.export",r.UnitId);var units=a.InWorkspace(a.Visible(tenant,"members.read"),tenant,r.UnitId).Select(u=>u.Id);var q=db.Memberships.Where(m=>m.TenantId==tenant&&units.Contains(m.ChapterId)&&m.JoinedAt>=begin&&m.JoinedAt<through&&(r.Status==null||m.Status==r.Status));return await Rows((from m in q join p in db.Persons on m.PersonId equals p.Id join u in db.Units on m.ChapterId equals u.Id join c in db.MembershipCategories on m.CategoryId equals c.Id orderby m.JoinedAt,m.Id select new{m.Id,m.Number,p.FullName,chapter=u.Name,category=c.Name,m.Status,m.JoinedAt,m.EffectiveFrom,m.EndsAt}));}
  if(r.Report=="Leadership"){await a.Require(tenant,"governance.manage",r.UnitId);var units=a.InWorkspace(a.Visible(tenant,"governance.manage"),tenant,r.UnitId).Select(u=>u.Id);return await Rows((from o in db.OfficerAppointments join p in db.OfficerPositions on o.PositionId equals p.Id where o.TenantId==tenant&&o.UnitId!=null&&units.Contains(o.UnitId.Value)&&o.StartsAt<through&&o.EndsAt>=begin&&(r.Status==null||o.Status==r.Status) orderby o.StartsAt,o.Id select new{o.Id,position=p.Name,o.MembershipId,o.UnitId,o.Status,o.StartsAt,o.EndsAt}));}
  if(r.Report=="Activities")return await Rows(community.Posts(tenant).Where(p=>p.PublishedAt>=begin&&p.PublishedAt<through&&(r.Status==null||p.Status==r.Status)&&(r.UnitId==null||p.UnitId!=null&&a.InWorkspace(a.Visible(tenant,"activities.read"),tenant,r.UnitId).Select(u=>u.Id).Contains(p.UnitId.Value))).OrderByDescending(p=>p.PublishedAt).ThenBy(p=>p.Id).Select(p=>new{p.Id,p.Title,p.UnitId,p.Status,p.PublishedAt,p.Achievement}));
  if(r.Report=="Events")return await Rows(community.Events(tenant).Where(e=>e.StartsAt>=begin&&e.StartsAt<through&&(r.Status==null||e.Status==r.Status)&&(r.UnitId==null||e.UnitId!=null&&a.InWorkspace(a.Visible(tenant,"activities.read"),tenant,r.UnitId).Select(u=>u.Id).Contains(e.UnitId.Value))).OrderBy(e=>e.StartsAt).ThenBy(e=>e.Id).Select(e=>new{e.Id,e.Title,e.UnitId,e.Status,e.StartsAt,e.EndsAt,e.Venue}));
  if(r.Report=="Attendance"){await a.Require(tenant,"events.analytics",r.UnitId);var units=a.InWorkspace(a.Visible(tenant,"events.analytics"),tenant,r.UnitId).Select(u=>u.Id);return await Rows((from v in db.Set<EventAttendance>() join e in db.Set<CommunityEvent>() on v.EventId equals e.Id where v.TenantId==tenant&&!v.Voided&&v.At>=begin&&v.At<through&&e.UnitId!=null&&units.Contains(e.UnitId.Value) orderby v.At,v.Id select new{v.Id,eventTitle=e.Title,v.RegistrationId,v.PeopleCount,v.At}));}
  if(r.Report=="Communication"){await a.Require(tenant,"communications.analytics",r.UnitId);var units=a.InWorkspace(a.Visible(tenant,"communications.analytics"),tenant,r.UnitId).Select(u=>u.Id);var global=await a.Can(tenant,"communications.analytics");return await Rows(db.Outbox.Where(o=>o.TenantId==tenant&&(o.UnitId!=null&&units.Contains(o.UnitId.Value)||o.UnitId==null&&global)&&o.CreatedAt>=begin&&o.CreatedAt<through&&(r.Status==null||o.Status==r.Status)).OrderBy(o=>o.CreatedAt).ThenBy(o=>o.Id).Select(o=>new{o.Id,o.Channel,o.Status,o.CreatedAt,o.SentAt,o.DeliveredAt,o.Attempts}));}
  if(r.Report is "Member Dues" or "Chapter Dues" or "Payments"){await a.Require(tenant,"finance.export",r.UnitId);var source=r.Report=="Payments"?"Collections":r.Report;var data=Json(await FinanceEndpoints.UnifiedReport(tenant,source,r.EntityId,r.UnitId,r.From,r.To,page,db,a,finance));var items=data.GetProperty("items").EnumerateArray().Select(x=>x.Clone()).ToArray();return new(data.TryGetProperty("total",out var total)?total.GetInt32():items.Length,items,"Financial source records; legal entity and currency remain separate");}
  if(r.Report=="Service Projects")return await Rows(service.Visible(tenant,r.UnitId).Where(p=>p.StartsOn<=DateOnly.FromDateTime(through)&&p.EndsOn>=DateOnly.FromDateTime(begin)&&(r.Status==null||p.Status==r.Status)).OrderBy(p=>p.StartsOn).ThenBy(p=>p.Id).Select(p=>new{p.Id,p.Name,p.Category,p.UnitId,p.Status,p.StartsOn,p.EndsOn,p.BudgetId}));
  if(r.Report=="Volunteer Hours"){await a.Require(tenant,"service.coordinate",r.UnitId);var projects=service.Visible(tenant,r.UnitId).Select(p=>p.Id);return await Rows(db.Set<VolunteerAttendance>().Where(v=>v.TenantId==tenant&&v.Status=="Verified"&&v.CheckedIn>=begin&&v.CheckedIn<through&&db.Set<VolunteerShift>().Any(s=>s.Id==v.ShiftId&&projects.Contains(s.ProjectId))).OrderBy(v=>v.CheckedIn).ThenBy(v=>v.Id).Select(v=>new{v.Id,v.MembershipId,v.ShiftId,v.Hours,v.CheckedIn,v.CheckedOut,v.Status}));}
  if(r.Report is "ID Cards" or "Certificates"){await a.Require(tenant,"studio.read",r.UnitId);var units=a.InWorkspace(a.Visible(tenant,"studio.read"),tenant,r.UnitId).Select(u=>u.Id);var kind=r.Report=="ID Cards"?"Card":"Certificate";return await Rows(db.Set<Credential>().Where(c=>c.TenantId==tenant&&c.UnitId!=null&&units.Contains(c.UnitId.Value)&&c.Kind==kind&&c.At>=begin&&c.At<through&&(r.Status==null||c.Status==r.Status)).OrderBy(c=>c.At).ThenBy(c=>c.Id).Select(c=>new{c.Id,c.Serial,c.MembershipId,c.UnitId,c.Category,c.Status,c.IssueDate,c.ExpiryDate,c.TemplateVersionId}));}
  throw new DomainException("Unsupported report");
 }
 public async Task<byte[]> Export(Guid tenant,UnifiedReportRequest request,FinanceDocuments pdf){if(request.Format is not("pdf" or "csv" or "xlsx"))throw new DomainException("Choose PDF, CSV or XLSX");var rows=new List<JsonElement>();for(var page=1;page<=2000;page++){var result=await Report(tenant,request,page);rows.AddRange(result.Items);if(request.Format=="pdf"&&rows.Count>5000)throw new DomainException("PDF supports up to 5,000 records; use CSV/XLSX for larger reports");if(rows.Count>=result.Total)break;if(page==2000)throw new DomainException("Narrow this export to at most 200,000 rows");}if(request.Format=="pdf")return pdf.Render(request.Report,"Authorized unified report · source-specific permissions applied",rows.SelectMany((r,i)=>r.EnumerateObject().Select(p=>((i+1)+" · "+p.Name,p.Value.ToString()))),"Assemblia · Authorized report");return FinanceExport.Encode(request.Report,request.Format,rows,pdf);}
}

public static partial class FinanceEndpoints {
 public static Task<object> UnifiedReport(Guid tenant,string report,Guid? entity,Guid? unit,DateOnly? from,DateOnly? to,int page,AppDb db,Access a,FinanceService service)=>Report(tenant,report,entity,unit,null,null,null,from,to,page,db,a,service);
}
